/* ===================================================== */
/* PIPELINE NODE */
/* ===================================================== */

function PipelineNode({
  icon: Icon,
  title,
  value,
  tone,
}: {
  icon: React.ElementType
  title: string
  value: string
  tone: 'primary' | 'success'
}) {
  return (
    <div
      className={cn(
        'rounded-lg border p-2.5',
        tone === 'primary'
          ? 'border-primary/15 bg-primary/[0.025]'
          : 'border-success/15 bg-success/[0.025]',
      )}
    >

      <div className="flex items-center gap-2">

        <Icon
          className={cn(
            'size-3.5',
            tone === 'primary'
              ? 'text-primary'
              : 'text-success',
          )}
        />

        <div className="min-w-0">

          <p className="font-mono text-[7px] uppercase tracking-wider text-muted-foreground">
            {title}
          </p>

          <p className="truncate font-mono text-[8px] font-bold text-foreground">
            {value}
          </p>

        </div>

      </div>

    </div>
  )
}


